// Writes src/fixtures/core-1.generated.ts. Run: pnpm --filter @loadstate/core fixtures:generate
import { writeFileSync } from "node:fs";
import { generateCorePack } from "./fixtures.ts";

const { manifest, data } = generateCorePack();

const lines = [
  "// Generated by packages/core/scripts/generate-fixtures.ts. Do not edit by hand:",
  "// run `pnpm --filter @loadstate/core fixtures:generate` and review the diff.",
  'import type { FixtureManifest, PackData } from "../contracts.js";',
  "",
  `export const manifest: FixtureManifest = ${JSON.stringify(manifest, null, 2)};`,
  "",
  "export const data: PackData = {",
  ...Object.entries(data).flatMap(([name, records]: [string, unknown[]]) => [
    `  ${name}: [`,
    ...records.map((record) => `    ${JSON.stringify(record)},`),
    "  ],",
  ]),
  "};",
  "",
];

const target = new URL("../src/fixtures/core-1.generated.ts", import.meta.url);
writeFileSync(target, lines.join("\n"));
console.log(`Wrote ${manifest.id} (${manifest.checksum}) to ${target.pathname}`);
